<script>(()=>{const form=document.getElementById('vendorApproveForm');const button=document.getElementById('vendor-approve-button');button?.addEventListener('click',async()=>{button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm me-1"></span>Approving...';try{const response=await fetch(form.action,{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:new FormData(form)});const data=await response.json();if(!response.ok)throw new Error(data.message||'Unable to approve order.');window.location.href=data.redirect_url||'{{ route('vendor.orders.index',['tab'=>'approved']) }}';}catch(error){button.disabled=false;button.innerHTML='<i class="fa-solid fa-circle-check me-1"></i>Approve Order';alert(error.message);}});const rejectForm=document.getElementById('vendorRejectForm');rejectForm?.addEventListener('submit',async event=>{event.preventDefault();if(!rejectForm.reportValidity())return;const submit=rejectForm.querySelector('[type=submit]');submit.disabled=true;try{const response=await fetch(rejectForm.action,{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:new FormData(rejectForm)});const data=await response.json();if(!response.ok)throw new Error(data.message||'Unable to reject order.');window.location.href=data.redirect_url||'{{ route('vendor.orders.index',['tab'=>'pending']) }}';}catch(error){submit.disabled=false;alert(error.message);}});})();</script>
